"""
自定义异常模块

定义代码Memory系统中使用的所有异常类型。
"""


class CodeMemoryError(Exception):
    """代码Memory系统基础异常"""
    pass


# ============ 解析相关异常 ============

class ParserError(CodeMemoryError):
    """解析器异常基类"""
    pass


class UnsupportedLanguageError(ParserError):
    """不支持的编程语言"""

    def __init__(self, language: str):
        self.language = language
        super().__init__(f"Unsupported language: {language}")


class ParseFailedError(ParserError):
    """代码解析失败"""

    def __init__(self, file_path: str, reason: str):
        self.file_path = file_path
        self.reason = reason
        super().__init__(f"Failed to parse {file_path}: {reason}")


class SyntaxError_(ParserError):
    """语法错误"""

    def __init__(self, file_path: str, line: int, column: int, message: str):
        self.file_path = file_path
        self.line = line
        self.column = column
        super().__init__(f"Syntax error in {file_path}:{line}:{column}: {message}")


# ============ 存储相关异常 ============

class StorageError(CodeMemoryError):
    """存储异常基类"""
    pass


class StorageConnectionError(StorageError):
    """存储连接失败"""

    def __init__(self, backend: str, reason: str):
        self.backend = backend
        self.reason = reason
        super().__init__(f"Failed to connect to {backend}: {reason}")


class StorageNotFoundError(StorageError):
    """存储数据未找到"""

    def __init__(self, entity_type: str, entity_id: str):
        self.entity_type = entity_type
        self.entity_id = entity_id
        super().__init__(f"{entity_type} not found: {entity_id}")


class StorageWriteError(StorageError):
    """存储写入失败"""

    def __init__(self, operation: str, reason: str):
        self.operation = operation
        self.reason = reason
        super().__init__(f"Failed to {operation}: {reason}")


class DuplicateEntityError(StorageError):
    """实体重复"""

    def __init__(self, entity_id: str):
        self.entity_id = entity_id
        super().__init__(f"Entity already exists: {entity_id}")


# ============ 索引相关异常 ============

class IndexError_(CodeMemoryError):
    """索引异常基类"""
    pass


class IndexBuildError(IndexError_):
    """索引构建失败"""

    def __init__(self, index_type: str, reason: str):
        self.index_type = index_type
        self.reason = reason
        super().__init__(f"Failed to build {index_type} index: {reason}")


class IndexCorruptedError(IndexError_):
    """索引损坏"""

    def __init__(self, index_path: str):
        self.index_path = index_path
        super().__init__(f"Index corrupted: {index_path}")


# ============ 嵌入相关异常 ============

class EmbeddingError(CodeMemoryError):
    """嵌入异常基类"""
    pass


class EmbeddingModelError(EmbeddingError):
    """嵌入模型错误"""

    def __init__(self, model_name: str, reason: str):
        self.model_name = model_name
        self.reason = reason
        super().__init__(f"Embedding model error ({model_name}): {reason}")


class EmbeddingDimensionMismatch(EmbeddingError):
    """嵌入维度不匹配"""

    def __init__(self, expected: int, actual: int):
        self.expected = expected
        self.actual = actual
        super().__init__(f"Embedding dimension mismatch: expected {expected}, got {actual}")


# ============ 检索相关异常 ============

class RetrievalError(CodeMemoryError):
    """检索异常基类"""
    pass


class QueryParseError(RetrievalError):
    """查询解析失败"""

    def __init__(self, query: str, reason: str):
        self.query = query
        self.reason = reason
        super().__init__(f"Failed to parse query: {reason}")


class NoResultsError(RetrievalError):
    """无检索结果"""

    def __init__(self, query: str):
        self.query = query
        super().__init__(f"No results found for query: {query}")


# ============ 图相关异常 ============

class GraphError(CodeMemoryError):
    """图操作异常基类"""
    pass


class NodeNotFoundError(GraphError):
    """图节点未找到"""

    def __init__(self, node_id: str):
        self.node_id = node_id
        super().__init__(f"Node not found: {node_id}")


class EdgeNotFoundError(GraphError):
    """图边未找到"""

    def __init__(self, source_id: str, target_id: str, relation_type: str):
        self.source_id = source_id
        self.target_id = target_id
        self.relation_type = relation_type
        super().__init__(
            f"Edge not found: {source_id} -[{relation_type}]-> {target_id}"
        )


class CycleDetectedError(GraphError):
    """检测到循环依赖"""

    def __init__(self, cycle_path: list):
        self.cycle_path = cycle_path
        cycle_str = " -> ".join(cycle_path)
        super().__init__(f"Cycle detected: {cycle_str}")


# ============ Memory相关异常 ============

class MemoryError_(CodeMemoryError):
    """Memory操作异常基类"""
    pass


class MemoryCapacityExceeded(MemoryError_):
    """Memory容量超限"""

    def __init__(self, memory_type: str, limit: int, current: int):
        self.memory_type = memory_type
        self.limit = limit
        self.current = current
        super().__init__(
            f"{memory_type} capacity exceeded: {current}/{limit}"
        )


class SessionExpiredError(MemoryError_):
    """会话已过期"""

    def __init__(self, session_id: str):
        self.session_id = session_id
        super().__init__(f"Session expired: {session_id}")


# ============ 配置相关异常 ============

class ConfigError(CodeMemoryError):
    """配置异常基类"""
    pass


class InvalidConfigError(ConfigError):
    """无效配置"""

    def __init__(self, config_key: str, reason: str):
        self.config_key = config_key
        self.reason = reason
        super().__init__(f"Invalid config '{config_key}': {reason}")


class MissingConfigError(ConfigError):
    """缺少必要配置"""

    def __init__(self, config_key: str):
        self.config_key = config_key
        super().__init__(f"Missing required config: {config_key}")

"""
基础数据模型

定义所有模型的基类和通用数据结构。
"""

from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from datetime import datetime
from typing import Any, Dict, List, Optional, Tuple
import hashlib
import json
import uuid


@dataclass
class BaseModel(ABC):
    """
    模型基类

    所有数据模型都继承自此类，提供通用的ID生成、序列化等功能。
    """
    id: str = field(default_factory=lambda: str(uuid.uuid4()))
    created_at: datetime = field(default_factory=datetime.now)
    updated_at: datetime = field(default_factory=datetime.now)
    metadata: Dict[str, Any] = field(default_factory=dict)

    def update_timestamp(self) -> None:
        """更新修改时间戳"""
        self.updated_at = datetime.now()

    def to_dict(self) -> Dict[str, Any]:
        """转换为字典"""
        result = {}
        for key, value in self.__dict__.items():
            if isinstance(value, datetime):
                result[key] = value.isoformat()
            elif isinstance(value, BaseModel):
                result[key] = value.to_dict()
            elif isinstance(value, list):
                result[key] = [
                    v.to_dict() if isinstance(v, BaseModel) else v 
                    for v in value
                ]
            elif hasattr(value, 'value'):  # Enum
                result[key] = value.value
            else:
                result[key] = value
        return result

    def to_json(self) -> str:
        """转换为JSON字符串"""
        return json.dumps(self.to_dict(), ensure_ascii=False, indent=2)

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "BaseModel":
        """从字典创建实例"""
        # 处理时间戳
        if 'created_at' in data and isinstance(data['created_at'], str):
            data['created_at'] = datetime.fromisoformat(data['created_at'])
        if 'updated_at' in data and isinstance(data['updated_at'], str):
            data['updated_at'] = datetime.fromisoformat(data['updated_at'])
        return cls(**data)

    def compute_hash(self) -> str:
        """计算对象哈希值"""
        content = json.dumps(self.to_dict(), sort_keys=True)
        return hashlib.sha256(content.encode()).hexdigest()[:16]

    def __hash__(self) -> int:
        return hash(self.id)

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, BaseModel):
            return False
        return self.id == other.id


@dataclass
class LocationInfo:
    """
    代码位置信息

    记录代码元素在文件中的精确位置。
    """
    file_path: str
    start_line: int
    end_line: int
    start_col: int = 0
    end_col: int = 0
    start_byte: Optional[int] = None
    end_byte: Optional[int] = None

    def __str__(self) -> str:
        return f"{self.file_path}:{self.start_line}:{self.start_col}"

    def contains(self, line: int, col: int = 0) -> bool:
        """检查给定位置是否在此范围内"""
        if line < self.start_line or line > self.end_line:
            return False
        if line == self.start_line and col < self.start_col:
            return False
        if line == self.end_line and col > self.end_col:
            return False
        return True

    def overlaps(self, other: "LocationInfo") -> bool:
        """检查两个位置是否重叠"""
        if self.file_path != other.file_path:
            return False
        return not (
            self.end_line < other.start_line or 
            other.end_line < self.start_line
        )

    def to_tuple(self) -> Tuple[str, int, int, int, int]:
        """转换为元组"""
        return (
            self.file_path,
            self.start_line,
            self.end_line,
            self.start_col,
            self.end_col,
        )


@dataclass
class ParameterInfo:
    """
    函数参数信息

    记录函数/方法参数的详细信息。
    """
    name: str
    type_annotation: Optional[str] = None
    default_value: Optional[str] = None
    is_variadic: bool = False  # *args
    is_keyword: bool = False   # **kwargs
    is_positional_only: bool = False
    is_keyword_only: bool = False

    def __str__(self) -> str:
        parts = []
        if self.is_variadic:
            parts.append("*")
        elif self.is_keyword:
            parts.append("**")
        parts.append(self.name)
        if self.type_annotation:
            parts.append(f": {self.type_annotation}")
        if self.default_value:
            parts.append(f" = {self.default_value}")
        return "".join(parts)

    @property
    def has_default(self) -> bool:
        """是否有默认值"""
        return self.default_value is not None

    @property
    def is_typed(self) -> bool:
        """是否有类型注解"""
        return self.type_annotation is not None


@dataclass
class ImportInfo:
    """
    导入信息

    记录代码中的导入语句信息。
    """
    module_name: str
    imported_names: List[str] = field(default_factory=list)  # from x import a, b
    alias: Optional[str] = None  # import x as y
    is_relative: bool = False
    level: int = 0  # 相对导入层级 (from ..x import y -> level=2)
    location: Optional[LocationInfo] = None

    def __str__(self) -> str:
        if self.imported_names:
            names = ", ".join(self.imported_names)
            if self.is_relative:
                dots = "." * self.level
                return f"from {dots}{self.module_name} import {names}"
            return f"from {self.module_name} import {names}"
        else:
            result = f"import {self.module_name}"
            if self.alias:
                result += f" as {self.alias}"
            return result

    @property
    def full_module_path(self) -> str:
        """获取完整模块路径"""
        if self.is_relative:
            return "." * self.level + self.module_name
        return self.module_name


@dataclass
class DecoratorInfo:
    """
    装饰器信息
    """
    name: str
    arguments: List[str] = field(default_factory=list)
    location: Optional[LocationInfo] = None

    def __str__(self) -> str:
        if self.arguments:
            args = ", ".join(self.arguments)
            return f"@{self.name}({args})"
        return f"@{self.name}"


@dataclass 
class TypeInfo:
    """
    类型信息

    记录类型注解的详细信息，支持泛型类型。
    """
    base_type: str
    type_args: List["TypeInfo"] = field(default_factory=list)
    is_optional: bool = False
    is_union: bool = False
    union_types: List["TypeInfo"] = field(default_factory=list)

    def __str__(self) -> str:
        if self.is_union:
            types_str = " | ".join(str(t) for t in self.union_types)
            return types_str
        if self.is_optional:
            return f"Optional[{self.base_type}]"
        if self.type_args:
            args_str = ", ".join(str(t) for t in self.type_args)
            return f"{self.base_type}[{args_str}]"
        return self.base_type

    @classmethod
    def from_string(cls, type_str: str) -> "TypeInfo":
        """从字符串解析类型信息（简化版本）"""
        type_str = type_str.strip()

        # 处理Optional
        if type_str.startswith("Optional[") and type_str.endswith("]"):
            inner = type_str[9:-1]
            return cls(base_type=inner, is_optional=True)

        # 处理Union
        if "|" in type_str:
            parts = [p.strip() for p in type_str.split("|")]
            return cls(
                base_type="Union",
                is_union=True,
                union_types=[cls.from_string(p) for p in parts]
            )

        # 处理泛型
        if "[" in type_str and type_str.endswith("]"):
            bracket_idx = type_str.index("[")
            base = type_str[:bracket_idx]
            args_str = type_str[bracket_idx + 1:-1]
            # 简化处理，不处理嵌套泛型的逗号分割
            args = [a.strip() for a in args_str.split(",")]
            return cls(
                base_type=base,
                type_args=[cls.from_string(a) for a in args]
            )

        return cls(base_type=type_str)


@dataclass
class DocstringInfo:
    """
    文档字符串信息

    解析后的文档字符串，包含描述、参数说明、返回值说明等。
    """
    summary: str = ""
    description: str = ""
    params: Dict[str, str] = field(default_factory=dict)
    returns: Optional[str] = None
    raises: Dict[str, str] = field(default_factory=dict)
    examples: List[str] = field(default_factory=list)
    notes: List[str] = field(default_factory=list)
    raw: str = ""

    @classmethod
    def parse(cls, docstring: str) -> "DocstringInfo":
        """解析文档字符串（简化版本，支持Google/NumPy风格）"""
        if not docstring:
            return cls()

        lines = docstring.strip().split("\n")
        info = cls(raw=docstring)

        # 第一行作为摘要
        if lines:
            info.summary = lines[0].strip()

        # 简化处理，将剩余内容作为描述
        if len(lines) > 1:
            info.description = "\n".join(lines[1:]).strip()

        return info

"""
图结构模型

定义代码关系图（调用图、继承图、依赖图等）的数据模型。
"""

from dataclasses import dataclass, field
from datetime import datetime
from enum import Enum
from typing import Any, Dict, List, Optional, Set, Tuple, Iterator
from collections import defaultdict

from code_memory.models.base import BaseModel
from code_memory.models.relations import RelationType, CodeRelation


class GraphType(Enum):
    """图类型"""
    CALL_GRAPH = "call_graph"
    INHERITANCE_GRAPH = "inheritance_graph"
    DEPENDENCY_GRAPH = "dependency_graph"
    DATA_FLOW_GRAPH = "data_flow_graph"
    CONTROL_FLOW_GRAPH = "control_flow_graph"
    MIXED = "mixed"


@dataclass
class GraphNode:
    """
    图节点

    表示代码关系图中的一个节点。
    """
    id: str
    label: str = ""
    node_type: str = ""  # 对应EntityType

    # 节点属性
    properties: Dict[str, Any] = field(default_factory=dict)

    # 嵌入向量
    embedding: Optional[List[float]] = None

    # 关联的代码实体ID
    entity_id: Optional[str] = None

    # 节点位置信息（用于可视化）
    x: float = 0.0
    y: float = 0.0

    def __hash__(self) -> int:
        return hash(self.id)

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, GraphNode):
            return False
        return self.id == other.id


@dataclass
class GraphEdge:
    """
    图边

    表示代码关系图中的一条边。
    """
    source_id: str
    target_id: str
    edge_type: str = ""  # 对应RelationType

    # 边属性
    weight: float = 1.0
    properties: Dict[str, Any] = field(default_factory=dict)

    # 边的唯一标识
    @property
    def id(self) -> str:
        return f"{self.source_id}:{self.edge_type}:{self.target_id}"

    def __hash__(self) -> int:
        return hash(self.id)

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, GraphEdge):
            return False
        return self.id == other.id


@dataclass
class CodeGraph(BaseModel):
    """
    代码关系图基类

    通用的图数据结构，支持有向/无向图。
    """
    graph_type: GraphType = GraphType.MIXED
    name: str = ""
    description: str = ""

    # 图的方向性
    is_directed: bool = True

    # 节点和边
    _nodes: Dict[str, GraphNode] = field(default_factory=dict)
    _edges: Dict[str, GraphEdge] = field(default_factory=dict)

    # 邻接表（用于快速查询）
    _adj: Dict[str, Set[str]] = field(default_factory=lambda: defaultdict(set))  # 出边
    _radj: Dict[str, Set[str]] = field(default_factory=lambda: defaultdict(set))  # 入边

    # ============ 节点操作 ============

    def add_node(self, node: GraphNode) -> None:
        """添加节点"""
        self._nodes[node.id] = node

    def remove_node(self, node_id: str) -> bool:
        """删除节点"""
        if node_id not in self._nodes:
            return False

        # 删除相关的边
        for target_id in list(self._adj[node_id]):
            self.remove_edge(node_id, target_id)
        for source_id in list(self._radj[node_id]):
            self.remove_edge(source_id, node_id)

        del self._nodes[node_id]
        return True

    def get_node(self, node_id: str) -> Optional[GraphNode]:
        """获取节点"""
        return self._nodes.get(node_id)

    def has_node(self, node_id: str) -> bool:
        """检查节点是否存在"""
        return node_id in self._nodes

    @property
    def nodes(self) -> List[GraphNode]:
        """获取所有节点"""
        return list(self._nodes.values())

    @property
    def node_count(self) -> int:
        """节点数量"""
        return len(self._nodes)

    # ============ 边操作 ============

    def add_edge(self, edge: GraphEdge) -> None:
        """添加边"""
        self._edges[edge.id] = edge
        self._adj[edge.source_id].add(edge.target_id)
        self._radj[edge.target_id].add(edge.source_id)

    def remove_edge(self, source_id: str, target_id: str, edge_type: str = "") -> bool:
        """删除边"""
        edge_id = f"{source_id}:{edge_type}:{target_id}"
        if edge_id not in self._edges:
            return False

        del self._edges[edge_id]
        self._adj[source_id].discard(target_id)
        self._radj[target_id].discard(source_id)
        return True

    def get_edge(self, source_id: str, target_id: str, edge_type: str = "") -> Optional[GraphEdge]:
        """获取边"""
        edge_id = f"{source_id}:{edge_type}:{target_id}"
        return self._edges.get(edge_id)

    def has_edge(self, source_id: str, target_id: str) -> bool:
        """检查边是否存在"""
        return target_id in self._adj.get(source_id, set())

    @property
    def edges(self) -> List[GraphEdge]:
        """获取所有边"""
        return list(self._edges.values())

    @property
    def edge_count(self) -> int:
        """边数量"""
        return len(self._edges)

    # ============ 邻居查询 ============

    def successors(self, node_id: str) -> List[str]:
        """获取后继节点（出边目标）"""
        return list(self._adj.get(node_id, set()))

    def predecessors(self, node_id: str) -> List[str]:
        """获取前驱节点（入边来源）"""
        return list(self._radj.get(node_id, set()))

    def neighbors(self, node_id: str) -> List[str]:
        """获取所有相邻节点"""
        return list(
            self._adj.get(node_id, set()) | self._radj.get(node_id, set())
        )

    def out_degree(self, node_id: str) -> int:
        """出度"""
        return len(self._adj.get(node_id, set()))

    def in_degree(self, node_id: str) -> int:
        """入度"""
        return len(self._radj.get(node_id, set()))

    def degree(self, node_id: str) -> int:
        """度（入度+出度）"""
        return self.in_degree(node_id) + self.out_degree(node_id)

    # ============ 图算法 ============

    def bfs(self, start_id: str, max_depth: int = -1) -> Iterator[Tuple[str, int]]:
        """广度优先遍历"""
        if start_id not in self._nodes:
            return

        visited = {start_id}
        queue = [(start_id, 0)]

        while queue:
            node_id, depth = queue.pop(0)
            yield node_id, depth

            if max_depth >= 0 and depth >= max_depth:
                continue

            for neighbor_id in self.successors(node_id):
                if neighbor_id not in visited:
                    visited.add(neighbor_id)
                    queue.append((neighbor_id, depth + 1))

    def dfs(self, start_id: str, max_depth: int = -1) -> Iterator[Tuple[str, int]]:
        """深度优先遍历"""
        if start_id not in self._nodes:
            return

        visited = set()
        stack = [(start_id, 0)]

        while stack:
            node_id, depth = stack.pop()

            if node_id in visited:
                continue

            visited.add(node_id)
            yield node_id, depth

            if max_depth >= 0 and depth >= max_depth:
                continue

            for neighbor_id in reversed(self.successors(node_id)):
                if neighbor_id not in visited:
                    stack.append((neighbor_id, depth + 1))

    def shortest_path(self, source_id: str, target_id: str) -> Optional[List[str]]:
        """寻找最短路径（BFS）"""
        if source_id not in self._nodes or target_id not in self._nodes:
            return None

        if source_id == target_id:
            return [source_id]

        visited = {source_id}
        queue = [(source_id, [source_id])]

        while queue:
            node_id, path = queue.pop(0)

            for neighbor_id in self.successors(node_id):
                if neighbor_id == target_id:
                    return path + [neighbor_id]

                if neighbor_id not in visited:
                    visited.add(neighbor_id)
                    queue.append((neighbor_id, path + [neighbor_id]))

        return None  # 不可达

    def has_cycle(self) -> bool:
        """检测是否有环"""
        WHITE, GRAY, BLACK = 0, 1, 2
        color = {node_id: WHITE for node_id in self._nodes}

        def dfs(node_id: str) -> bool:
            color[node_id] = GRAY
            for neighbor_id in self.successors(node_id):
                if color[neighbor_id] == GRAY:
                    return True  # 发现回边
                if color[neighbor_id] == WHITE and dfs(neighbor_id):
                    return True
            color[node_id] = BLACK
            return False

        for node_id in self._nodes:
            if color[node_id] == WHITE:
                if dfs(node_id):
                    return True

        return False

    def find_cycles(self) -> List[List[str]]:
        """查找所有环（简化版，只找简单环）"""
        cycles = []
        visited = set()

        def dfs(node_id: str, path: List[str]) -> None:
            if node_id in path:
                cycle_start = path.index(node_id)
                cycle = path[cycle_start:] + [node_id]
                # 归一化环（从最小ID开始）
                min_idx = cycle.index(min(cycle))
                normalized = cycle[min_idx:-1] + cycle[:min_idx] + [cycle[min_idx]]
                if normalized not in cycles:
                    cycles.append(normalized)
                return

            if node_id in visited:
                return

            visited.add(node_id)
            path.append(node_id)

            for neighbor_id in self.successors(node_id):
                dfs(neighbor_id, path.copy())

        for node_id in self._nodes:
            dfs(node_id, [])

        return cycles

    def topological_sort(self) -> Optional[List[str]]:
        """拓扑排序（如果有环则返回None）"""
        in_degree = {node_id: self.in_degree(node_id) for node_id in self._nodes}
        queue = [node_id for node_id, d in in_degree.items() if d == 0]
        result = []

        while queue:
            node_id = queue.pop(0)
            result.append(node_id)

            for neighbor_id in self.successors(node_id):
                in_degree[neighbor_id] -= 1
                if in_degree[neighbor_id] == 0:
                    queue.append(neighbor_id)

        return result if len(result) == len(self._nodes) else None

    def subgraph(self, node_ids: Set[str]) -> "CodeGraph":
        """提取子图"""
        subgraph = CodeGraph(
            graph_type=self.graph_type,
            name=f"{self.name}_subgraph",
            is_directed=self.is_directed,
        )

        for node_id in node_ids:
            if node_id in self._nodes:
                subgraph.add_node(self._nodes[node_id])

        for edge in self._edges.values():
            if edge.source_id in node_ids and edge.target_id in node_ids:
                subgraph.add_edge(edge)

        return subgraph


@dataclass
class CallGraph(CodeGraph):
    """
    函数调用图

    表示函数/方法之间的调用关系。
    """
    graph_type: GraphType = field(default=GraphType.CALL_GRAPH)

    # 入口点（没有被其他函数调用的函数）
    @property
    def entry_points(self) -> List[str]:
        """获取入口点"""
        return [
            node_id for node_id in self._nodes
            if self.in_degree(node_id) == 0
        ]

    # 叶子节点（不调用其他函数的函数）
    @property
    def leaf_functions(self) -> List[str]:
        """获取叶子函数"""
        return [
            node_id for node_id in self._nodes
            if self.out_degree(node_id) == 0
        ]

    def get_call_chain(
        self,
        start_id: str,
        end_id: str,
        max_depth: int = 10
    ) -> List[List[str]]:
        """获取从start到end的所有调用链"""
        chains = []

        def dfs(current: str, path: List[str], depth: int) -> None:
            if depth > max_depth:
                return

            if current == end_id:
                chains.append(path.copy())
                return

            for callee_id in self.successors(current):
                if callee_id not in path:  # 避免循环
                    path.append(callee_id)
                    dfs(callee_id, path, depth + 1)
                    path.pop()

        dfs(start_id, [start_id], 0)
        return chains

    def get_callers(self, function_id: str, depth: int = 1) -> Set[str]:
        """获取调用指定函数的所有函数（向上追溯）"""
        callers = set()
        for node_id, d in self.bfs(function_id, max_depth=depth):
            # 使用反向遍历
            if d > 0:
                callers.update(self.predecessors(node_id))
        return callers

    def get_callees(self, function_id: str, depth: int = 1) -> Set[str]:
        """获取指定函数调用的所有函数（向下追溯）"""
        callees = set()
        for node_id, d in self.bfs(function_id, max_depth=depth):
            if d > 0:
                callees.add(node_id)
        return callees


@dataclass
class InheritanceTree(CodeGraph):
    """
    类继承图

    表示类之间的继承关系（实际上是DAG，因为支持多继承）。
    """
    graph_type: GraphType = field(default=GraphType.INHERITANCE_GRAPH)

    @property
    def root_classes(self) -> List[str]:
        """获取根类（没有基类的类）"""
        return [
            node_id for node_id in self._nodes
            if self.out_degree(node_id) == 0  # 没有继承任何类
        ]

    @property
    def leaf_classes(self) -> List[str]:
        """获取叶子类（没有子类的类）"""
        return [
            node_id for node_id in self._nodes
            if self.in_degree(node_id) == 0
        ]

    def get_ancestors(self, class_id: str) -> Set[str]:
        """获取所有祖先类"""
        ancestors = set()
        for node_id, _ in self.dfs(class_id):
            if node_id != class_id:
                ancestors.add(node_id)
        return ancestors

    def get_descendants(self, class_id: str) -> Set[str]:
        """获取所有后代类"""
        descendants = set()
        # 使用反向遍历
        visited = set()
        queue = [class_id]

        while queue:
            current = queue.pop(0)
            for child_id in self.predecessors(current):
                if child_id not in visited:
                    visited.add(child_id)
                    descendants.add(child_id)
                    queue.append(child_id)

        return descendants

    def get_mro(self, class_id: str) -> List[str]:
        """获取方法解析顺序（简化版C3线性化）"""
        # 简化实现，实际应该使用C3线性化算法
        result = [class_id]
        visited = {class_id}
        queue = list(self.successors(class_id))

        while queue:
            current = queue.pop(0)
            if current not in visited:
                visited.add(current)
                result.append(current)
                queue.extend(self.successors(current))

        return result


@dataclass
class DependencyGraph(CodeGraph):
    """
    模块依赖图

    表示模块之间的导入/依赖关系。
    """
    graph_type: GraphType = field(default=GraphType.DEPENDENCY_GRAPH)

    @property
    def root_modules(self) -> List[str]:
        """获取根模块（不依赖其他模块的模块）"""
        return [
            node_id for node_id in self._nodes
            if self.out_degree(node_id) == 0
        ]

    @property
    def leaf_modules(self) -> List[str]:
        """获取叶子模块（没有被其他模块依赖的模块）"""
        return [
            node_id for node_id in self._nodes
            if self.in_degree(node_id) == 0
        ]

    def get_dependencies(self, module_id: str, transitive: bool = False) -> Set[str]:
        """获取模块的依赖"""
        if not transitive:
            return set(self.successors(module_id))

        deps = set()
        for node_id, _ in self.dfs(module_id):
            if node_id != module_id:
                deps.add(node_id)
        return deps

    def get_dependents(self, module_id: str, transitive: bool = False) -> Set[str]:
        """获取依赖此模块的其他模块"""
        if not transitive:
            return set(self.predecessors(module_id))

        dependents = set()
        visited = set()
        queue = [module_id]

        while queue:
            current = queue.pop(0)
            for dependent_id in self.predecessors(current):
                if dependent_id not in visited:
                    visited.add(dependent_id)
                    dependents.add(dependent_id)
                    queue.append(dependent_id)

        return dependents

    def get_circular_dependencies(self) -> List[List[str]]:
        """查找循环依赖"""
        return self.find_cycles()

    def get_layered_order(self) -> Optional[List[Set[str]]]:
        """获取分层顺序（每层可以并行处理）"""
        if self.has_cycle():
            return None

        in_degree = {node_id: self.in_degree(node_id) for node_id in self._nodes}
        layers = []
        remaining = set(self._nodes.keys())

        while remaining:
            # 找出当前层（入度为0的节点）
            current_layer = {
                node_id for node_id in remaining
                if in_degree[node_id] == 0
            }

            if not current_layer:
                break  # 有环，无法继续

            layers.append(current_layer)
            remaining -= current_layer

            # 更新入度
            for node_id in current_layer:
                for successor_id in self.successors(node_id):
                    if successor_id in remaining:
                        in_degree[successor_id] -= 1

        return layers if not remaining else None

