from .base import BaseVectorStore, SearchResult


class InMemoryVectorStore(BaseVectorStore):
    """
    内存向量存储

    简单的内存实现，适用于小规模数据或测试。
    使用暴力搜索计算余弦相似度。
    """

    def __init__(
        self,
        collection_name: str = "default",
        dimension: int = 768,
        **kwargs
    ):
        """初始化内存向量存储"""
        super().__init__(collection_name, dimension, **kwargs)
        self._vectors: Dict[str, List[float]] = {}
        self._metadatas: Dict[str, Dict[str, Any]] = {}
        self._documents: Dict[str, str] = {}

    def add(
        self,
        ids: List[str],
        embeddings: List[List[float]],
        metadatas: Optional[List[Dict[str, Any]]] = None,
        documents: Optional[List[str]] = None,
    ) -> None:
        """添加向量"""
        metadatas = metadatas or [{}] * len(ids)
        documents = documents or [""] * len(ids)

        for i, id_ in enumerate(ids):
            self._vectors[id_] = embeddings[i]
            self._metadatas[id_] = metadatas[i]
            self._documents[id_] = documents[i]

    def search(
        self,
        query_embedding: List[float],
        top_k: int = 10,
        filter: Optional[Dict[str, Any]] = None,
    ) -> List[SearchResult]:
        """向量相似度搜索"""
        results = []

        for id_, embedding in self._vectors.items():
            # 应用过滤器
            if filter:
                metadata = self._metadatas.get(id_, {})
                if not self._matches_filter(metadata, filter):
                    continue

            # 计算余弦相似度
            score = self._cosine_similarity(query_embedding, embedding)

            results.append(SearchResult(
                id=id_,
                score=score,
                data={'document': self._documents.get(id_, '')},
                embedding=embedding,
                metadata=self._metadatas.get(id_, {}),
            ))

        # 按分数降序排序
        results.sort(key=lambda x: x.score, reverse=True)

        return results[:top_k]

    def get(self, ids: List[str]) -> List[Optional[Dict[str, Any]]]:
        """按ID获取向量"""
        results = []
        for id_ in ids:
            if id_ in self._vectors:
                results.append({
                    'id': id_,
                    'embedding': self._vectors[id_],
                    'metadata': self._metadatas.get(id_, {}),
                    'document': self._documents.get(id_, ''),
                })
            else:
                results.append(None)
        return results

    def update(
        self,
        ids: List[str],
        embeddings: Optional[List[List[float]]] = None,
        metadatas: Optional[List[Dict[str, Any]]] = None,
        documents: Optional[List[str]] = None,
    ) -> None:
        """更新向量"""
        for i, id_ in enumerate(ids):
            if id_ in self._vectors:
                if embeddings:
                    self._vectors[id_] = embeddings[i]
                if metadatas:
                    self._metadatas[id_] = metadatas[i]
                if documents:
                    self._documents[id_] = documents[i]

    def delete(self, ids: List[str]) -> None:
        """删除向量"""
        for id_ in ids:
            self._vectors.pop(id_, None)
            self._metadatas.pop(id_, None)
            self._documents.pop(id_, None)

    def count(self) -> int:
        """获取向量数量"""
        return len(self._vectors)

    def clear(self) -> None:
        """清空集合"""
        self._vectors.clear()
        self._metadatas.clear()
        self._documents.clear()

    def _cosine_similarity(
        self,
        vec1: List[float],
        vec2: List[float],
    ) -> float:
        """计算余弦相似度"""
        dot_product = sum(a * b for a, b in zip(vec1, vec2))
        norm1 = math.sqrt(sum(a * a for a in vec1))
        norm2 = math.sqrt(sum(b * b for b in vec2))

        if norm1 == 0 or norm2 == 0:
            return 0.0

        return dot_product / (norm1 * norm2)

    def _matches_filter(
        self,
        metadata: Dict[str, Any],
        filter: Dict[str, Any],
    ) -> bool:
        """检查元数据是否匹配过滤条件"""
        for key, value in filter.items():
            if key not in metadata:
                return False
            if metadata[key] != value:
                return False
        return True


class FAISSVectorStore(BaseVectorStore):
    """
    FAISS向量存储

    使用Facebook的FAISS库进行高效向量检索。
    """

    def __init__(
        self,
        collection_name: str = "default",
        dimension: int = 768,
        index_type: str = "Flat",  # Flat, IVF, HNSW
        **kwargs
    ):
        """
        初始化FAISS向量存储

        Args:
            collection_name: 集合名称
            dimension: 向量维度
            index_type: 索引类型
        """
        super().__init__(collection_name, dimension, **kwargs)
        self._index_type = index_type
        self._index = None
        self._id_to_idx: Dict[str, int] = {}
        self._idx_to_id: Dict[int, str] = {}
        self._metadatas: Dict[str, Dict[str, Any]] = {}
        self._documents: Dict[str, str] = {}
        self._next_idx = 0

        self._init_index()

    def _init_index(self):
        """初始化FAISS索引"""
        try:
            import faiss

            if self._index_type == "Flat":
                self._index = faiss.IndexFlatIP(self._dimension)  # 内积（用于归一化向量的余弦相似度）
            elif self._index_type == "IVF":
                quantizer = faiss.IndexFlatIP(self._dimension)
                self._index = faiss.IndexIVFFlat(quantizer, self._dimension, 100)
            elif self._index_type == "HNSW":
                self._index = faiss.IndexHNSWFlat(self._dimension, 32)
            else:
                self._index = faiss.IndexFlatIP(self._dimension)

        except ImportError:
            # 如果没有安装FAISS，使用内存存储作为后备
            self._index = None
            self._vectors: Dict[str, List[float]] = {}

    def add(
        self,
        ids: List[str],
        embeddings: List[List[float]],
        metadatas: Optional[List[Dict[str, Any]]] = None,
        documents: Optional[List[str]] = None,
    ) -> None:
        """添加向量"""
        metadatas = metadatas or [{}] * len(ids)
        documents = documents or [""] * len(ids)

        if self._index is not None:
            import numpy as np

            # 归一化向量
            vectors = np.array(embeddings, dtype=np.float32)
            faiss = __import__('faiss')
            faiss.normalize_L2(vectors)

            # 添加到索引
            self._index.add(vectors)

            # 记录ID映射
            for i, id_ in enumerate(ids):
                idx = self._next_idx + i
                self._id_to_idx[id_] = idx
                self._idx_to_id[idx] = id_
                self._metadatas[id_] = metadatas[i]
                self._documents[id_] = documents[i]

            self._next_idx += len(ids)
        else:
            # 后备内存存储
            for i, id_ in enumerate(ids):
                self._vectors[id_] = embeddings[i]
                self._metadatas[id_] = metadatas[i]
                self._documents[id_] = documents[i]

    def search(
        self,
        query_embedding: List[float],
        top_k: int = 10,
        filter: Optional[Dict[str, Any]] = None,
    ) -> List[SearchResult]:
        """向量相似度搜索"""
        if self._index is not None:
            import numpy as np

            # 归一化查询向量
            query = np.array([query_embedding], dtype=np.float32)
            faiss = __import__('faiss')
            faiss.normalize_L2(query)

            # 搜索
            k = min(top_k * 2, self._index.ntotal)  # 多取一些以处理过滤
            if k == 0:
                return []

            scores, indices = self._index.search(query, k)

            results = []
            for score, idx in zip(scores[0], indices[0]):
                if idx < 0:
                    continue

                id_ = self._idx_to_id.get(int(idx))
                if not id_:
                    continue

                # 应用过滤器
                if filter:
                    metadata = self._metadatas.get(id_, {})
                    if not self._matches_filter(metadata, filter):
                        continue

                results.append(SearchResult(
                    id=id_,
                    score=float(score),
                    data={'document': self._documents.get(id_, '')},
                    metadata=self._metadatas.get(id_, {}),
                ))

                if len(results) >= top_k:
                    break

            return results
        else:
            # 后备暴力搜索
            return self._brute_force_search(query_embedding, top_k, filter)

    def _brute_force_search(
        self,
        query_embedding: List[float],
        top_k: int,
        filter: Optional[Dict[str, Any]],
    ) -> List[SearchResult]:
        """暴力搜索后备方法"""
        results = []

        for id_, embedding in self._vectors.items():
            if filter:
                metadata = self._metadatas.get(id_, {})
                if not self._matches_filter(metadata, filter):
                    continue

            score = self._cosine_similarity(query_embedding, embedding)
            results.append(SearchResult(
                id=id_,
                score=score,
                data={'document': self._documents.get(id_, '')},
                metadata=self._metadatas.get(id_, {}),
            ))

        results.sort(key=lambda x: x.score, reverse=True)
        return results[:top_k]

    def _cosine_similarity(self, vec1: List[float], vec2: List[float]) -> float:
        """计算余弦相似度"""
        dot_product = sum(a * b for a, b in zip(vec1, vec2))
        norm1 = math.sqrt(sum(a * a for a in vec1))
        norm2 = math.sqrt(sum(b * b for b in vec2))
        if norm1 == 0 or norm2 == 0:
            return 0.0
        return dot_product / (norm1 * norm2)

    def _matches_filter(self, metadata: Dict[str, Any], filter: Dict[str, Any]) -> bool:
        """检查过滤条件"""
        for key, value in filter.items():
            if key not in metadata or metadata[key] != value:
                return False
        return True

    def get(self, ids: List[str]) -> List[Optional[Dict[str, Any]]]:
        """按ID获取向量"""
        results = []
        for id_ in ids:
            if id_ in self._metadatas:
                results.append({
                    'id': id_,
                    'metadata': self._metadatas[id_],
                    'document': self._documents.get(id_, ''),
                })
            else:
                results.append(None)
        return results

    def update(
        self,
        ids: List[str],
        embeddings: Optional[List[List[float]]] = None,
        metadatas: Optional[List[Dict[str, Any]]] = None,
        documents: Optional[List[str]] = None,
    ) -> None:
        """更新向量（FAISS不支持原地更新，需要重建索引）"""
        for i, id_ in enumerate(ids):
            if metadatas:
                self._metadatas[id_] = metadatas[i]
            if documents:
                self._documents[id_] = documents[i]

        # 注意：FAISS不支持更新向量，需要删除后重新添加
        if embeddings:
            # 简化处理：只更新元数据
            pass

    def delete(self, ids: List[str]) -> None:
        """删除向量"""
        for id_ in ids:
            self._metadatas.pop(id_, None)
            self._documents.pop(id_, None)
            if id_ in self._id_to_idx:
                idx = self._id_to_idx.pop(id_)
                self._idx_to_id.pop(idx, None)

    def count(self) -> int:
        """获取向量数量"""
        if self._index is not None:
            return self._index.ntotal
        return len(getattr(self, '_vectors', {}))

    def clear(self) -> None:
        """清空集合"""
        self._id_to_idx.clear()
        self._idx_to_id.clear()
        self._metadatas.clear()
        self._documents.clear()
        self._next_idx = 0
        self._init_index()


class ChromaVectorStore(BaseVectorStore):
    """
    Chroma向量存储

    使用ChromaDB进行向量存储和检索。
    """

    def __init__(
        self,
        collection_name: str = "default",
        dimension: int = 768,
        persist_directory: Optional[str] = None,
        **kwargs
    ):
        """
        初始化Chroma向量存储

        Args:
            collection_name: 集合名称
            dimension: 向量维度
            persist_directory: 持久化目录
        """
        super().__init__(collection_name, dimension, **kwargs)
        self._persist_directory = persist_directory
        self._client = None
        self._collection = None

        self._init_client()

    def _init_client(self):
        """初始化Chroma客户端"""
        try:
            import chromadb
            from chromadb.config import Settings

            if self._persist_directory:
                self._client = chromadb.Client(Settings(
                    chroma_db_impl="duckdb+parquet",
                    persist_directory=self._persist_directory,
                ))
            else:
                self._client = chromadb.Client()

            self._collection = self._client.get_or_create_collection(
                name=self._collection_name,
                metadata={"hnsw:space": "cosine"}
            )

        except ImportError:
            # 如果没有安装Chroma，使用内存存储
            self._fallback = InMemoryVectorStore(
                self._collection_name, 
                self._dimension
            )

    def add(
        self,
        ids: List[str],
        embeddings: List[List[float]],
        metadatas: Optional[List[Dict[str, Any]]] = None,
        documents: Optional[List[str]] = None,
    ) -> None:
        """添加向量"""
        if self._collection is not None:
            self._collection.add(
                ids=ids,
                embeddings=embeddings,
                metadatas=metadatas,
                documents=documents,
            )
        elif hasattr(self, '_fallback'):
            self._fallback.add(ids, embeddings, metadatas, documents)

    def search(
        self,
        query_embedding: List[float],
        top_k: int = 10,
        filter: Optional[Dict[str, Any]] = None,
    ) -> List[SearchResult]:
        """向量相似度搜索"""
        if self._collection is not None:
            results = self._collection.query(
                query_embeddings=[query_embedding],
                n_results=top_k,
                where=filter,
            )

            search_results = []
            if results['ids'] and results['ids'][0]:
                for i, id_ in enumerate(results['ids'][0]):
                    search_results.append(SearchResult(
                        id=id_,
                        score=1 - results['distances'][0][i] if results['distances'] else 0,
                        data={'document': results['documents'][0][i] if results['documents'] else ''},
                        metadata=results['metadatas'][0][i] if results['metadatas'] else {},
                    ))

            return search_results
        elif hasattr(self, '_fallback'):
            return self._fallback.search(query_embedding, top_k, filter)
        return []

    def get(self, ids: List[str]) -> List[Optional[Dict[str, Any]]]:
        """按ID获取向量"""
        if self._collection is not None:
            results = self._collection.get(ids=ids, include=['embeddings', 'metadatas', 'documents'])

            output = []
            for i, id_ in enumerate(ids):
                if id_ in results['ids']:
                    idx = results['ids'].index(id_)
                    output.append({
                        'id': id_,
                        'embedding': results['embeddings'][idx] if results['embeddings'] else None,
                        'metadata': results['metadatas'][idx] if results['metadatas'] else {},
                        'document': results['documents'][idx] if results['documents'] else '',
                    })
                else:
                    output.append(None)
            return output
        elif hasattr(self, '_fallback'):
            return self._fallback.get(ids)
        return [None] * len(ids)

    def update(
        self,
        ids: List[str],
        embeddings: Optional[List[List[float]]] = None,
        metadatas: Optional[List[Dict[str, Any]]] = None,
        documents: Optional[List[str]] = None,
    ) -> None:
        """更新向量"""
        if self._collection is not None:
            self._collection.update(
                ids=ids,
                embeddings=embeddings,
                metadatas=metadatas,
                documents=documents,
            )
        elif hasattr(self, '_fallback'):
            self._fallback.update(ids, embeddings, metadatas, documents)

    def delete(self, ids: List[str]) -> None:
        """删除向量"""
        if self._collection is not None:
            self._collection.delete(ids=ids)
        elif hasattr(self, '_fallback'):
            self._fallback.delete(ids)

    def count(self) -> int:
        """获取向量数量"""
        if self._collection is not None:
            return self._collection.count()
        elif hasattr(self, '_fallback'):
            return self._fallback.count()
        return 0

    def clear(self) -> None:
        """清空集合"""
        if self._client is not None:
            self._client.delete_collection(self._collection_name)
            self._collection = self._client.create_collection(
                name=self._collection_name,
                metadata={"hnsw:space": "cosine"}
            )
        elif hasattr(self, '_fallback'):
            self._fallback.clear()
